package dev.pedro.learning.ecommerce.inventory.api; import dev.pedro.learning.ecommerce.inventory.domain.InventoryItem; import java.util.UUID; public record InventoryItemResponse(UUID productId,int availableQuantity,int reservedQuantity){public static InventoryItemResponse from(InventoryItem i){return new InventoryItemResponse(i.productId,i.availableQuantity,i.reservedQuantity);}}